const $ = (s, el=document)=>el.querySelector(s);
const $$ = (s, el=document)=>[...el.querySelectorAll(s)];
const state={page:'home',products:[],stores:[],favorites:[],cart:JSON.parse(localStorage.getItem('collectra_cart')||'[]'),device:localStorage.getItem('collectra_device')||crypto.randomUUID(),selectedCategory:'All',selectedStore:null,verifyFiles:{},evidenceContext:null,evidenceBlob:null,evidenceReviewUrl:'',evidenceRecorder:null,evidenceStream:null,evidenceChunks:[],evidenceStep:0,evidenceStartedAt:0,adminKey:localStorage.getItem('collectra_admin_key')||'',sellerToken:localStorage.getItem('collectra_seller_token')||'',lang:localStorage.getItem('collectra_lang')||'en',demoMode:false,_feedbackRating:0};

const I18N={
en:{nav_home:'Home',nav_shops:'Shops',nav_verify:'Verify Card',nav_sell:'Sell',nav_support:'Support',nav_saved:'Saved',nav_profile:'Profile',nav_cart:'Cart',
hero_title_1:'Collect. Verify.',hero_title_2:'Trade with Confidence.',hero_p:'Collectra is a mobile-first marketplace for collectible cards with verified stores, guided AI-assisted card checks, saved favorites, secure transaction evidence, and human support when you need it.',hero_btn_shops:'Explore Shops',hero_btn_verify:'Verify a Card',
marketplace:'Marketplace',marketplace_p:'Demo stock is included. Sellers can upload real stock from Seller Tools.',
verify_title:'Verify Your Card',verify_p:'All four views are required before AI screening can start.',
sell_title:'Sell on Collectra',orders_title:'Orders',seller_orders_title:'Seller Orders',support_title:'Collectra Support',admin_title:'Collectra Admin',shops_title:'Shops',cart_title:'Cart',profile_title:'Profile'},
th:{nav_home:'หน้าแรก',nav_shops:'ร้านค้า',nav_verify:'ตรวจการ์ด',nav_sell:'ขายของ',nav_support:'ช่วยเหลือ',nav_saved:'รายการโปรด',nav_profile:'โปรไฟล์',nav_cart:'ตะกร้า',
hero_title_1:'สะสม ตรวจสอบ',hero_title_2:'ซื้อขายอย่างมั่นใจ',hero_p:'Collectra คือตลาดซื้อขายการ์ดสะสมบนมือถือ พร้อมร้านค้าที่ยืนยันตัวตน ตรวจสอบการ์ดด้วย AI แบบมีขั้นตอนนำทาง บันทึกรายการโปรด หลักฐานการทำธุรกรรมที่ปลอดภัย และทีมงานมนุษย์พร้อมช่วยเหลือเมื่อคุณต้องการ',hero_btn_shops:'ดูร้านค้า',hero_btn_verify:'ตรวจสอบการ์ด',
marketplace:'ตลาดซื้อขาย',marketplace_p:'มีสินค้าตัวอย่างให้ทดลองใช้งาน ผู้ขายสามารถอัปโหลดสินค้าจริงได้จากเครื่องมือผู้ขาย',
verify_title:'ตรวจสอบการ์ดของคุณ',verify_p:'ต้องใช้ภาพครบทั้ง 4 มุมก่อนเริ่มการตรวจสอบด้วย AI',
sell_title:'ขายของบน Collectra',orders_title:'คำสั่งซื้อ',seller_orders_title:'คำสั่งซื้อของผู้ขาย',support_title:'ศูนย์ช่วยเหลือ Collectra',admin_title:'ผู้ดูแลระบบ Collectra',shops_title:'ร้านค้า',cart_title:'ตะกร้าสินค้า',profile_title:'โปรไฟล์'}
};
function t(key){return (I18N[state.lang]&&I18N[state.lang][key])||I18N.en[key]||key}
function toggleLang(){state.lang=state.lang==='en'?'th':'en';localStorage.setItem('collectra_lang',state.lang);render()}
function logoMark(){return `<svg viewBox="0 0 225 66" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Collectra"><path d="M43.53,39.91 A17,17 0 1 1 43.53,26.09" stroke="#8fb7e8" stroke-width="8" fill="none" stroke-linecap="round"/><path d="M45.5 14.5 L47.7 19.3 L52.5 21.5 L47.7 23.7 L45.5 28.5 L43.3 23.7 L38.5 21.5 L43.3 19.3 Z" fill="#f0c96b"/><text x="64" y="39" font-family="system-ui,-apple-system,'Segoe UI',sans-serif" font-weight="500" font-size="23" letter-spacing="2.5" fill="#5b7396">COLLECTRA</text></svg>`}
localStorage.setItem('collectra_device',state.device);

const icons={home:'⌂',shops:'▦',sell:'＋',saved:'♡',profile:'◎',verify:'✓',search:'⌕',cart:'🛒'};
const DEMO_ONLY=window.COLLECTRA_DEMO_ONLY===true;
const DEMO_ALLOWED_PAGES=['seller-demo','seller-demo-feedback','seller-orders','seller-dashboard','seller-tools','seller-login','evidence-recorder'];
const money=n=>'฿'+Number(n||0).toLocaleString(undefined,{maximumFractionDigits:2});
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const api=async(url,opts={})=>{const r=await fetch(url,opts);let d={};try{d=await r.json()}catch{}if(!r.ok){const e=new Error(d.error||'Request failed');e.data=d;throw e}return d};
function toast(msg){const t=document.createElement('div');t.className='toast';t.textContent=msg;document.body.appendChild(t);setTimeout(()=>t.remove(),2400)}
function saveCart(){localStorage.setItem('collectra_cart',JSON.stringify(state.cart))}
function setPage(p){if(DEMO_ONLY&&!DEMO_ALLOWED_PAGES.includes(p))p='seller-demo';state.page=p;location.hash=p;render()}

async function bootstrap(){
  if(DEMO_ONLY){
    const hash=location.hash.replace('#','');
    state.page=DEMO_ALLOWED_PAGES.includes(hash)?hash:'seller-demo';
    render();
    return;
  }
  try{
    [state.products,state.stores,state.favorites]=await Promise.all([
      api('/api/products'),api('/api/stores'),api('/api/favorites?device_id='+encodeURIComponent(state.device))
    ]);
  }catch(e){console.error(e);toast('Could not load data')}
  const hash=location.hash.replace('#',''); if(hash)state.page=hash; render();
  if((location.protocol==='https:'||location.hostname==='localhost')&&'serviceWorker' in navigator){navigator.serviceWorker.register('/sw.js').catch(()=>{})}
}
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p){state.page=p;render()}});

function header(){if(DEMO_ONLY)return `
<header class="desktop-top">
  <button class="brand ghost" onclick="setPage('seller-demo')" style="cursor:default">${logoMark()}</button>
  <div class="top-actions"><span class="sub" style="font-weight:800">Seller Workflow Demo</span></div>
</header>`;return `
<header class="desktop-top">
  <button class="brand ghost" onclick="setPage('home')">${logoMark()}</button>
  <nav class="desktop-links">
    <button onclick="setPage('home')">${t('nav_home')}</button><button onclick="setPage('shops')">${t('nav_shops')}</button><button onclick="setPage('verify')">${t('nav_verify')}</button><button onclick="setPage('sell')">${t('nav_sell')}</button><button onclick="setPage('support')">${t('nav_support')}</button>
  </nav>
  <div class="top-actions"><button class="ghost lang-toggle" onclick="toggleLang()" title="Switch language">${state.lang==='en'?'TH':'EN'}</button><button class="ghost" onclick="setPage('cart')">${t('nav_cart')} (${state.cart.reduce((a,b)=>a+b.qty,0)})</button><button class="btn btn-blue" onclick="setPage('profile')">${t('nav_profile')}</button></div>
</header>`}
function mobileNav(){if(DEMO_ONLY)return'';const cartCount=state.cart.reduce((a,b)=>a+b.qty,0);return `<button class="floating-verify" onclick="setPage('verify')">✓</button><nav class="mobile-nav">
${[['home','nav_home'],['shops','nav_shops'],['cart','nav_cart'],['sell','nav_sell'],['saved','nav_saved'],['profile','nav_profile']].map(([p,key])=>`<button class="${state.page===p?'active':''}" onclick="setPage('${p}')"><span class="nav-icon">${icons[p]}${p==='cart'&&cartCount?`<span class="nav-badge">${cartCount}</span>`:''}</span>${t(key)}</button>`).join('')}
</nav>`}
function shell(content){return `<div class="app-shell">${header()}<main class="page">${content}</main>${mobileNav()}</div>`}

function feature(icon,title,text){return `<div class="feature-card"><div class="feature-icon">${icon}</div><h3>${title}</h3><p>${text}</p></div>`}
function home(){
  const cats=['All','K-pop','T-pop','Other']; const filtered=state.selectedCategory==='All'?state.products:state.products.filter(p=>p.category===state.selectedCategory);
  return shell(`
  <section class="hero"><h1>${t('hero_title_1')}<br><em>${t('hero_title_2')}</em></h1><p>${t('hero_p')}</p><div class="hero-actions"><button class="btn btn-primary" onclick="setPage('shops')">${t('hero_btn_shops')}</button><button class="btn btn-white" onclick="setPage('verify')">${t('hero_btn_verify')}</button></div></section>
  <div class="feature-grid">${feature('✓','AI Verification','Guided front, back and detail photos.')}${feature('♡','Favorites','Save cards and stores for later.')}${feature('★','Verified Shops','Reviews, ratings and verification badges.')}${feature('💬','AI + Human Support','Start with AI, escalate to an admin.')}</div>
  <div class="section-head"><div><h2>${t('marketplace')}</h2><p>${t('marketplace_p')}</p></div></div>
  <div class="chips">${cats.map(c=>`<button class="chip ${state.selectedCategory===c?'active':''}" onclick="state.selectedCategory='${c}';render()">${c}</button>`).join('')}</div>
  <div class="product-grid" style="margin-top:14px">${filtered.map(productCard).join('')||'<div class="empty">No listings yet.</div>'}</div>
  `)}
function isFav(id){return state.favorites.some(p=>p.id===id)}
function aiListingTag(status){if(!status)return'';const cls=status==='Likely Authentic'?'good':status==='Suspicious'?'bad':'warn';const label=status==='Likely Authentic'?'✓ AI Authenticated':status==='Suspicious'?'AI: Suspicious':'AI: Needs Review';return `<span class="badge ai-tag ${cls}">${esc(label)}</span>`}
function productCard(p){return `<article class="product-card" onclick="openProduct(${p.id})"><div class="product-image-wrap"><img src="${p.image_url||'/assets/listing-demo-1.jpg'}" alt="${esc(p.title)}"><button class="heart ${isFav(p.id)?'active':''}" onclick="event.stopPropagation();toggleFavorite(${p.id})">${isFav(p.id)?'♥':'♡'}</button></div><div class="product-info"><h3>${esc(p.title)}</h3><div class="sub">${esc(p.store_name||'Store')} ${p.store_verified?'<span class="badge">✓ Verified</span>':''}</div>${aiListingTag(p.ai_status)}<div class="price">${money(p.price)}</div><div class="stock">${p.stock} in stock</div></div></article>`}
async function toggleFavorite(id){await api('/api/favorites',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({device_id:state.device,product_id:id})});state.favorites=await api('/api/favorites?device_id='+state.device);render();toast('Saved items updated')}
function openProduct(id){const p=state.products.find(x=>x.id===id);if(!p)return; const wrap=document.createElement('div');wrap.className='bottom-sheet-backdrop';wrap.innerHTML=`<div class="bottom-sheet"><div class="sheet-handle"></div><img class="detail-image" src="${p.image_url}" alt=""><div class="section-head"><div><h2>${esc(p.title)}</h2><p>${esc(p.category)} · ${esc(p.condition)}</p></div><button class="heart ${isFav(p.id)?'active':''}" onclick="toggleFavorite(${p.id});this.closest('.bottom-sheet-backdrop').remove()">${isFav(p.id)?'♥':'♡'}</button></div><div class="detail-price">${money(p.price)}</div><p>${esc(p.description||'')}</p><div class="notice ${p.store_verified?'good':'warn'}">${p.store_verified?'✓ Verified shop':'Seller is not yet verified'} · ${esc(p.store_name)}</div><div class="hero-actions"><button class="btn btn-primary" onclick="addCart(${p.id});this.closest('.bottom-sheet-backdrop').remove()">Add to Cart</button><button class="btn btn-blue" onclick="viewStore(${p.store_id});this.closest('.bottom-sheet-backdrop').remove()">View Store</button></div></div>`;wrap.onclick=e=>{if(e.target===wrap)wrap.remove()};document.body.appendChild(wrap)}
function addCart(id){const found=state.cart.find(x=>x.product_id===id);if(found)found.qty++;else state.cart.push({product_id:id,qty:1});saveCart();render();toast('Added to cart')}

function shops(){return shell(`<div class="section-head"><div><h1 class="screen-title">Verified Shops</h1><p>Open a store to see ratings, reviews and live listings.</p></div></div><div class="store-grid">${state.stores.map(storeCard).join('')}</div>`)}
function storeCard(s){return `<article class="store-card" onclick="viewStore(${s.id})"><div class="store-cover"><img src="${s.logo_url||'/assets/store-demo-1.svg'}" alt=""></div><div class="store-body"><div class="store-title"><div><h3 style="margin:0">${esc(s.name)}</h3><div class="sub">${esc(s.category)}</div></div>${s.verified?'<span class="verified">✓ Verified</span>':''}</div><p>${esc(s.description)}</p><div class="rating">★ ${s.rating||'New'} <span class="sub">(${s.review_count||0} reviews)</span></div></div></article>`}
async function viewStore(id){state.selectedStore=await api('/api/store?id='+id);state.page='store';render()}
function storePage(){const s=state.selectedStore;if(!s)return shops();return shell(`<button class="ghost" onclick="setPage('shops')">← Shops</button><div class="grid-2" style="margin-top:10px"><section class="panel blue"><h1>${esc(s.name)}</h1><p>${esc(s.description)}</p><div>${s.verified?'<span class="badge">✓ Collectra Verified</span>':'Not verified'}</div><h2>★ ${s.rating||'New'}</h2><p>${s.review_count} reviews</p></section><section class="panel yellow"><h2>Leave a Review</h2><div class="form-grid"><div class="field"><label>Rating</label><select id="reviewRating"><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select></div><div class="field"><label>Review</label><textarea id="reviewText" placeholder="How was your experience?"></textarea></div><button class="btn btn-blue" onclick="submitReview(${s.id})">Post Review</button></div></section></div><div class="section-head"><div><h2>Listings</h2><p>${s.products.length} current products</p></div></div><div class="product-grid">${s.products.map(productCard).join('')||'<div class="empty">No stock yet.</div>'}</div><div class="section-head"><div><h2>Reviews</h2></div></div><div class="panel">${s.reviews.map(r=>`<div class="admin-row"><div class="grow"><strong>${'★'.repeat(r.rating)}</strong><div>${esc(r.text)}</div></div><small>${new Date(r.created_at).toLocaleDateString()}</small></div>`).join('')||'No reviews yet.'}</div>`)}
async function submitReview(store_id){const rating=Number($('#reviewRating').value),text=$('#reviewText').value;await api('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({store_id,device_id:state.device,rating,text})});toast('Review posted');viewStore(store_id)}

function verify(){return shell(`<div class="section-head"><div><h1 class="screen-title">Verify Your Card</h1><p>All four views are required before AI screening can start.</p></div></div><div class="grid-2"><section class="panel blue"><h2>Required photo guide</h2><div class="photo-guide verify-guide-grid">${guide('1','Front','Full card, flat and centered')}${guide('2','Back','Full back, all corners visible')}${guide('3','Edges & corners','Close-up of borders and corners')}${guide('4','Surface details','Logo, print, foil or texture')}</div><div class="notice warn" style="margin-top:14px"><strong>Keep the same card throughout.</strong><br>Use good light, avoid glare, keep every image sharp, and do not crop out edges.</div></section><section class="panel"><div class="form-grid"><div class="field"><label>Category</label><select id="vCategory"><option>K-pop</option><option>T-pop</option><option>Other</option></select></div><div class="field"><label>Card name / set (optional)</label><input id="vName" placeholder="Artist, member, set or card name"></div>${verifyUpload('front','1. Front photo *')}${verifyUpload('back','2. Back photo *')}${verifyUpload('edges','3. Edges & corners detail *')}${verifyUpload('surface','4. Surface / logo / foil detail *')}<div class="progress"><span id="verifyProgress"></span></div><button class="btn btn-primary btn-full" onclick="submitVerification(this)">Start Verification</button><div class="sub">All four required images are compressed on your phone before upload to reduce waiting time.</div></div></section></div><div id="verifyResult" style="margin-top:18px"></div>`) }
function verifyUpload(kind,label){return `<div class="field required-upload"><label>${label}</label><input id="${kind}Input" type="file" accept="image/*" capture="environment" required onchange="handleVerifyFile('${kind}',this.files[0])"></div><div id="${kind}Preview"></div>`}
function guide(n,t,d){return `<div class="guide-card"><div class="guide-icon">${n}</div><div><strong>${t}</strong><div class="sub">${d}</div></div></div>`}
async function compressImage(file,max=1600,quality=.82){if(!file)return null;try{const img=await createImageBitmap(file);const scale=Math.min(1,max/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);const blob=await new Promise(res=>c.toBlob(res,'image/jpeg',quality));return new File([blob],(file.name.replace(/\.[^.]+$/,'')||'card')+'.jpg',{type:'image/jpeg'})}catch{return file}}
async function handleVerifyFile(kind,file){if(!file)return;state.verifyFiles[kind]=await compressImage(file);const url=URL.createObjectURL(state.verifyFiles[kind]);const el=$('#'+kind+'Preview');if(el)el.innerHTML=`<div class="capture-ok"><img class="preview-img" src="${url}"><span>✓ ${kind==='edges'?'Edges / corners':kind==='surface'?'Surface details':kind[0].toUpperCase()+kind.slice(1)} captured</span></div>`}
async function submitVerification(btn){const required=[['front','front'],['back','back'],['edges','edges & corners detail'],['surface','surface / logo / foil detail']];const missing=required.filter(([key])=>!state.verifyFiles[key]).map(([,label])=>label);if(missing.length)return toast('Required: '+missing.join(', '));btn.disabled=true;btn.textContent='Checking all views…';const prog=$('#verifyProgress');prog.style.width='20%';const fd=new FormData();fd.append('device_id',state.device);fd.append('category',$('#vCategory').value);fd.append('card_name',$('#vName').value);required.forEach(([key])=>fd.append(key,state.verifyFiles[key]));let timer=setInterval(()=>{let w=parseInt(prog.style.width)||20;prog.style.width=Math.min(90,w+5)+'%'},450);try{const r=await api('/api/verify',{method:'POST',body:fd});clearInterval(timer);prog.style.width='100%';const cls=r.verdict==='Likely Authentic'?'good':r.verdict==='Suspicious'?'bad':'warn';$('#verifyResult').innerHTML=`<div class="result-card"><div class="result-head"><div class="result-icon">${r.verdict==='Likely Authentic'?'✓':r.verdict==='Suspicious'?'!':'?'}</div><div><h2 style="margin:0">${esc(r.verdict)}</h2><div class="sub">${esc(r.provider)}</div></div><div class="grow"></div><div class="score">${r.confidence}<small>/100</small></div></div><p>${esc(r.summary)}</p><div class="notice ${cls}">${(r.details?.checks||r.details?.issues||[]).map(x=>'• '+esc(x)).join('<br>')||'All required views were received.'}</div><div class="hero-actions"><button class="btn btn-blue" onclick="setPage('support')">Ask AI Support</button><button class="btn btn-outline" onclick="requestHuman('Please manually review my latest card verification result.')">Request Human Review</button></div></div>`}catch(e){clearInterval(timer);toast(e.message)}finally{btn.disabled=false;btn.textContent='Start Verification'}}

function saved(){return shell(`<div class="section-head"><div><h1 class="screen-title">My Favorites</h1><p>Cards you saved for later.</p></div></div>${state.favorites.length?`<div class="product-grid">${state.favorites.map(productCard).join('')}</div>`:'<div class="empty"><div class="big">♡</div><h2>No saved cards yet</h2><p>Tap the heart on a listing.</p></div>'}`)}
function sell(){if(state.sellerToken)return shell(`<div class="section-head"><div><h1 class="screen-title">Sell on Collectra</h1><p>You're logged in as a seller on this device.</p></div></div><section class="panel"><h2>Continue to your store</h2><button class="btn btn-primary" onclick="setPage('seller-dashboard')">Open Seller Dashboard</button></section><section class="panel yellow"><h2>New here?</h2><div class="form-grid"><div class="field"><label>Shop name</label><input id="shopName" placeholder="Your shop name"></div><div class="field"><label>Email</label><input id="sellerEmail" type="email" placeholder="you@example.com"></div><div class="field"><label>Social link (optional)</label><input id="socialLink" placeholder="Your current shop/social page"></div><button class="btn btn-blue" onclick="sellerApply()">Submit Seller Request</button><div id="sellerMsg"></div></div></section>`);return shell(`<div class="section-head"><div><h1 class="screen-title">Sell on Collectra</h1><p>Apply first. Approved sellers receive a private store token for logging in.</p></div></div><div class="grid-2"><section class="panel"><h2>Already approved?</h2><p>Log in with your store token to manage listings and packing videos.</p><button class="btn btn-primary" onclick="setPage('seller-login')">Log In as Seller</button></section><section class="panel yellow"><h2>Become a Seller</h2><div class="form-grid"><div class="field"><label>Shop name</label><input id="shopName" placeholder="Your shop name"></div><div class="field"><label>Email</label><input id="sellerEmail" type="email" placeholder="you@example.com"></div><div class="field"><label>Social link (optional)</label><input id="socialLink" placeholder="Your current shop/social page"></div><button class="btn btn-blue" onclick="sellerApply()">Submit Seller Request</button><div id="sellerMsg"></div></div></section></div>`)}
function sellerLoginPage(){return shell(`<button class="ghost" onclick="setPage('sell')">← Sell</button><div class="section-head"><div><h1 class="screen-title">Seller Login</h1><p>Enter the store token you received after approval.</p></div></div><section class="panel"><div class="field"><label>Store token</label><input id="sellerLoginToken" placeholder="Token from Collectra admin"><button class="btn btn-blue" style="margin-top:10px" onclick="sellerLogin()">Log In</button><div id="sellerLoginMsg"></div></div></section>`)}
async function sellerLogin(){const token=($('#sellerLoginToken').value||'').trim();if(!token)return toast('Enter your store token');try{const r=await api('/api/seller-login?store_token='+encodeURIComponent(token));state.sellerToken=token;state._sellerStoreName=r.store.name;localStorage.setItem('collectra_seller_token',token);toast(`Logged in as ${r.store.name}`);setPage('seller-dashboard')}catch(e){$('#sellerLoginMsg').innerHTML=`<div class="notice bad">${esc(e.message)}</div>`}}
function sellerLogout(){state.sellerToken='';state._sellerStoreName='';state.demoMode=false;localStorage.removeItem('collectra_seller_token');toast('Logged out');setPage('sell')}
function demoBanner(){if(!state.demoMode)return'';return `<div class="notice warn" style="margin-bottom:14px;display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap"><span><strong>Seller demo mode.</strong> Testing the seller workflow — this is a sandbox store, not a real account.</span><button class="btn btn-outline" onclick="setPage('seller-demo-feedback')">Give Feedback</button></div>`}
function sellerDemoPage(){return shell(`<div class="section-head"><div><h1 class="screen-title">Try the Seller Workflow</h1><p>You're being asked to test what it's like to sell on Collectra — from receiving an order to proving it was packed correctly.</p></div></div><section class="panel blue"><h2>What you'll do</h2><ol style="margin:10px 0 0;padding-left:20px;line-height:1.9"><li>Log into a sandbox seller account (no signup needed)</li><li>See a demo order waiting to be packed</li><li>Record the guided packing video, following each on-screen step</li><li>See the AI check the video in real time as you record</li><li>Tell us what you liked and what felt confusing or annoying</li></ol></section><section class="panel yellow" style="margin-top:16px"><h2>Before you start</h2><p>This uses your camera to record a short video, the same as the real seller flow would. Nothing here is a real order or real payment — it's a sandbox store made just for testing.</p><button class="btn btn-primary btn-full" style="margin-top:10px" onclick="startSellerDemo()">Start Seller Demo</button></section>`)}
async function startSellerDemo(){try{const info=await api('/api/demo-seller-info');state.sellerToken=info.store_token;state._sellerStoreName=info.store_name;state.demoMode=true;localStorage.setItem('collectra_seller_token',info.store_token);toast('Logged into the demo seller account');setPage('seller-orders')}catch(e){toast(e.message)}}
function sellerDemoFeedbackPage(){return shell(`<button class="ghost" onclick="setPage('seller-dashboard')">← Back</button><div class="section-head"><div><h1 class="screen-title">How was that?</h1><p>Your feedback directly shapes what we build next — be as blunt as you like.</p></div></div><section class="panel"><div class="field"><label>Overall, how did recording the packing video feel?</label><div id="feedbackStars" style="display:flex;gap:8px;font-size:32px;margin:6px 0 14px">${[1,2,3,4,5].map(n=>`<span data-star="${n}" onclick="setFeedbackRating(${n})" style="cursor:pointer;opacity:.35">★</span>`).join('')}</div></div><div class="field"><label>What did you like?</label><textarea id="fbLiked" placeholder="e.g. the step-by-step guide was clear..."></textarea></div><div class="field"><label>What was confusing or annoying?</label><textarea id="fbImprove" placeholder="e.g. wasn't sure if the AI check meant I had to redo the step..."></textarea></div><button class="btn btn-primary btn-full" style="margin-top:6px" onclick="submitDemoFeedback()">Send Feedback</button><div id="fbMsg"></div></section>`)}
function setFeedbackRating(n){state._feedbackRating=n;$$('#feedbackStars span').forEach((el,i)=>{el.style.opacity=i<n?'1':'.35'})}
async function submitDemoFeedback(){try{const r=await api('/api/demo-feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role:'seller',rating:state._feedbackRating,liked:$('#fbLiked').value,improve:$('#fbImprove').value,device_id:state.device})});$('#fbMsg').innerHTML=`<div class="notice good" style="margin-top:12px">${esc(r.message)}</div>`;state._feedbackRating=0}catch(e){toast(e.message)}}
function sellerDashboardPage(){if(!state.sellerToken){setPage('seller-login');return''}return shell(`<button class="ghost" onclick="sellerLogout()">Log Out</button><div class="section-head"><div><h1 class="screen-title">${esc(state._sellerStoreName||'Seller Dashboard')}</h1><p>Manage your store from here.</p></div></div>${demoBanner()}<div class="grid-2"><section class="panel"><h2>Listings</h2><p>Upload new stock with real photos and quantities.</p><button class="btn btn-blue" onclick="setPage('seller-tools')">Upload Listing</button></section><section class="panel yellow"><h2>Packing Videos</h2><p>Record the required packing video for orders containing your items.</p><button class="btn btn-primary" onclick="setPage('seller-orders')">Open Seller Orders</button></section></div>`)}
async function sellerApply(){const email=$('#sellerEmail').value.trim();if(!email)return toast('Email required');const r=await api('/api/seller-applications',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,shop_name:$('#shopName').value,social_link:$('#socialLink').value})});$('#sellerMsg').innerHTML=`<div class="notice good">${esc(r.message)}</div>`}
function sellerTools(){const back=state.sellerToken?'seller-dashboard':'sell';return shell(`<button class="ghost" onclick="setPage('${back}')">← Back</button><div class="section-head"><div><h1 class="screen-title">Upload Listing</h1><p>Upload real stock to your approved store.</p></div></div><section class="panel"><form id="productForm" class="form-grid" onsubmit="uploadProduct(event)"><div class="field"><label>Store token</label><input name="store_token" required value="${esc(state.sellerToken||'')}" placeholder="Token from Collectra admin"></div><div class="grid-2"><div class="field"><label>Product title</label><input name="title" required></div><div class="field"><label>Category</label><select name="category"><option>K-pop</option><option>T-pop</option><option>Other</option></select></div></div><div class="grid-2"><div class="field"><label>Price (THB)</label><input name="price" type="number" min="0" step="0.01" required></div><div class="field"><label>Stock quantity</label><input name="stock" type="number" min="1" value="1" required></div></div><div class="field"><label>Condition</label><input name="condition" value="Like New"></div><div class="field"><label>Description</label><textarea name="description"></textarea></div><div class="notice" style="margin:2px 0 4px"><strong>AI authentication required before listing.</strong> Submit all 4 views of the physical card — the same photo checks buyers see on Verify Card. Listings flagged Suspicious won't be published.</div><div class="field"><label>Front photo *</label><input name="front" type="file" accept="image/*" capture="environment" required></div><div class="field"><label>Back photo *</label><input name="back" type="file" accept="image/*" capture="environment" required></div><div class="field"><label>Edges &amp; corners detail *</label><input name="edges" type="file" accept="image/*" capture="environment" required></div><div class="field"><label>Surface / logo / foil detail *</label><input name="surface" type="file" accept="image/*" capture="environment" required></div><button class="btn btn-blue">Authenticate &amp; Upload Listing</button><div id="uploadMsg"></div></form></section>`)}
function aiVerdictNotice(ai,extraMsg){if(!ai)return `<div class="notice bad">${esc(extraMsg||'')}</div>`;const cls=ai.status==='Verified'||ai.verdict==='Likely Authentic'?'good':(ai.status==='Suspicious'||ai.verdict==='Suspicious')?'bad':'warn';const verdict=ai.verdict||ai.status;return `<div class="notice ${cls}"><strong>AI check: ${esc(verdict)} (${ai.confidence}%)</strong><div class="sub" style="margin-top:4px">${esc(ai.summary||'')}</div>${extraMsg?`<div style="margin-top:8px">${esc(extraMsg)}</div>`:''}</div>`}
async function uploadProduct(e){e.preventDefault();const fd=new FormData(e.target);const b=$('button',e.target);b.disabled=true;b.textContent='Authenticating…';try{const r=await api('/api/products',{method:'POST',body:fd});$('#uploadMsg').innerHTML=aiVerdictNotice(r.ai,'✓ Listing is live.');state.products=await api('/api/products');e.target.reset()}catch(err){$('#uploadMsg').innerHTML=err.data?.ai?aiVerdictNotice(err.data.ai,err.message):`<div class="notice bad">${esc(err.message)}</div>`}finally{b.disabled=false;b.textContent='Authenticate & Upload Listing'}}

function support(){return shell(`<div class="section-head"><div><h1 class="screen-title">Collectra Support</h1><p>Start with the AI assistant, or ask for a real human admin.</p></div></div><section class="panel chat"><div class="quick-actions"><button onclick="sendQuick('How does card verification work?')">Verify a card</button><button onclick="sendQuick('How do I track my order?')">Track order</button><button onclick="sendQuick('How do I become a seller?')">Seller help</button><button onclick="requestHuman('I would like to speak to a human admin.')">Request Human Admin</button></div><div class="messages" id="messages"><div class="msg ai">Hi! I’m the Collectra AI assistant ✨ How can I help?</div></div><div class="chat-input"><input id="chatText" placeholder="Type your message…" onkeydown="if(event.key==='Enter')sendChat()"><button class="btn btn-blue" onclick="sendChat()">→</button></div></section>`)}
function addMsg(text,who){const el=$('#messages');if(!el)return;el.insertAdjacentHTML('beforeend',`<div class="msg ${who}">${esc(text)}</div>`);el.scrollTop=el.scrollHeight}
function sendQuick(t){$('#chatText').value=t;sendChat()}
async function sendChat(){const i=$('#chatText');const m=i.value.trim();if(!m)return;i.value='';addMsg(m,'user');addMsg('Thinking…','ai');try{const r=await api('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:m})});$('#messages .msg.ai:last-child').textContent=r.reply}catch{$('#messages .msg.ai:last-child').textContent='Could not reach support.'}}
async function requestHuman(message){const email=prompt('Email for the admin reply (optional):')||'';await api('/api/support-ticket',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({device_id:state.device,email,message})});toast('Human admin request sent')}

function cart(){const rows=state.cart.map(ci=>{const p=state.products.find(x=>x.id===ci.product_id);if(!p)return'';return `<div class="cart-row"><img src="${p.image_url}"><div class="grow"><strong>${esc(p.title)}</strong><div>${money(p.price)} × ${ci.qty}</div></div><button class="ghost" onclick="removeCart(${p.id})">Remove</button></div>`}).join('');const total=state.cart.reduce((sum,ci)=>{const p=state.products.find(x=>x.id===ci.product_id);return sum+(p?p.price*ci.qty:0)},0);return shell(`<div class="section-head"><div><h1 class="screen-title">Cart</h1><p>Your order reduces stock when checkout is created.</p></div></div><section class="panel">${rows||'<div class="empty">Cart is empty.</div>'}${state.cart.length?`<h2>Total ${money(total)}</h2><button class="btn btn-primary btn-full" onclick="setPage('checkout')">Checkout</button>`:''}</section>`)}
function removeCart(id){state.cart=state.cart.filter(x=>x.product_id!==id);saveCart();render()}
async function checkout(){const addrs=await api('/api/addresses?device_id='+state.device);state._addresses=addrs;state._useNewAddress=!addrs.length;state.page='checkout-ready';render()}
const ADDRESS_FIELDS=['label','name','phone','line1','district','city','province','postal'];
function addressFormFields(){return ADDRESS_FIELDS.map(k=>`<div class="field"><label>${k==='line1'?'Address line':k[0].toUpperCase()+k.slice(1)}</label><input name="${k}" ${['label','name','phone','line1','city','province','postal'].includes(k)?'required':''}></div>`).join('')}
function checkoutReady(){const addrs=state._addresses||[];const useNew=state._useNewAddress;return shell(`<div class="section-head"><div><h1 class="screen-title">Checkout</h1><p>Use a saved address or add a new one — no need to visit Profile first.</p></div></div><section class="panel">${addrs.length?`<div class="field"><label>Saved address</label><select id="checkoutAddress" onchange="state._useNewAddress=false;render()" ${useNew?'disabled':''}>${addrs.map(a=>`<option value="${a.id}">${esc(a.label)} — ${esc(a.line1)}, ${esc(a.city)}</option>`).join('')}</select></div>`:'<div class="notice warn">No saved address yet — add one below.</div>'}${addrs.length?`<button type="button" class="btn btn-outline btn-full" style="margin:12px 0" onclick="state._useNewAddress=${useNew?'false':'true'};render()">${useNew?'← Use a saved address instead':'+ Use a different address'}</button>`:''}<form id="newAddressForm" class="form-grid" style="${(useNew||!addrs.length)?'':'display:none'}">${addressFormFields()}</form><button class="btn btn-primary btn-full" style="margin-top:14px" onclick="createOrder()">Create Order</button></section>`)}
async function createOrder(){try{let address_id;const addrs=state._addresses||[];if(state._useNewAddress||!addrs.length){const form=$('#newAddressForm');const d=Object.fromEntries(new FormData(form));const required=['label','name','phone','line1','city','province','postal'];const missing=required.filter(k=>!d[k]);if(missing.length)return toast('Fill in: '+missing.join(', '));d.device_id=state.device;d.is_default=true;const ra=await api('/api/addresses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});address_id=ra.id}else{address_id=Number($('#checkoutAddress').value)}const r=await api('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({device_id:state.device,address_id,items:state.cart})});state.cart=[];saveCart();toast('Order created');state.lastOrder=r.order_id;setPage('orders')}catch(e){toast(e.message)}}

function profile(){return shell(`<div class="section-head"><div><h1 class="screen-title">Profile</h1><p>Your Collectra tools and saved information.</p></div></div><div class="feature-grid">${profileTile('📦','Orders','Tracking, payment slips and evidence','orders')}${profileTile('⌂','Addresses','Save delivery addresses','addresses')}${profileTile('💬','Support','AI chat or human admin','support')}${profileTile('⚙','Admin','Approve sellers and references','admin')}</div><section class="panel yellow" style="margin-top:18px"><h2>Install on your phone</h2><p>In Safari or Chrome, use <strong>Add to Home Screen</strong>. The site is designed to feel like a mobile app.</p></section>`)}
function profileTile(i,t,d,p){return `<button class="feature-card" style="text-align:left;border:1px solid #d6e6ff" onclick="setPage('${p}')"><div class="feature-icon">${i}</div><h3>${t}</h3><p>${d}</p></button>`}
async function addresses(){state._addresses=await api('/api/addresses?device_id='+state.device);state.page='addresses-ready';render()}
function addressesReady(){return shell(`<div class="section-head"><div><h1 class="screen-title">Saved Addresses</h1><p>Add an address once and reuse it at checkout — or add a new one right at checkout too.</p></div></div><div class="grid-2"><section class="panel"><h2>Your addresses</h2>${(state._addresses||[]).map(a=>`<div class="address-row"><div><strong>${esc(a.label)}</strong><div>${esc(a.name)} · ${esc(a.phone)}</div><div class="sub">${esc(a.line1)}, ${esc(a.city)}, ${esc(a.province)} ${esc(a.postal)}</div></div></div>`).join('')||'<div class="empty">No saved address yet.</div>'}</section><section class="panel yellow"><h2>Add Address</h2><form id="addressForm" class="form-grid" onsubmit="saveAddress(event)">${addressFormFields()}<button class="btn btn-blue">Save Address</button></form></section></div>`)}
async function saveAddress(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.device_id=state.device;d.is_default=true;await api('/api/addresses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});toast('Address saved');addresses()}
async function orders(){state._orders=await api('/api/orders?device_id='+state.device);state.page='orders-ready';render()}
function aiEvidenceBadge(status,confidence,summary,aiJson){if(!status)return'';const cls=status==='Verified'?'good':status==='Suspicious'?'bad':'warn';let authLine='';try{const j=aiJson?JSON.parse(aiJson):null;if(j&&j.authenticity_status){const acls=j.authenticity_status==='Likely Authentic'?'good':j.authenticity_status==='Suspicious'?'bad':'warn';authLine=`<div class="notice ${acls}" style="margin-top:4px"><strong>Card authenticity (from video): ${esc(j.authenticity_status)}${j.authenticity_confidence?` (${j.authenticity_confidence}%)`:''}</strong></div>`}}catch(e){}return `<div class="notice ${cls}" style="margin-top:6px"><strong>AI check: ${esc(status)}${confidence?` (${confidence}%)`:''}</strong>${summary?`<div class="sub">${esc(summary)}</div>`:''}</div>${authLine}`}
function ordersReady(){return shell(`<div class="section-head"><div><h1 class="screen-title">Orders</h1><p>Payment slips plus guided, uninterrupted packing and unboxing video evidence.</p></div></div>${(state._orders||[]).map(o=>`<section class="panel" style="margin-bottom:14px"><div class="store-title"><div><h2>Order #${o.id}</h2><div class="sub">${new Date(o.created_at).toLocaleString()}</div></div><span class="badge">${esc(o.status)}</span></div>${o.items.map(i=>`<div class="order-row"><div class="grow">${esc(i.title)}</div><strong>${i.qty} × ${money(i.unit_price)}</strong></div>`).join('')}<h3>Total ${money(o.total)}</h3><div class="notice ${o.payment_status==='slip_uploaded'?'good':'warn'}">Payment: ${esc(o.payment_status)}</div>${o.slip_url?aiEvidenceBadge(o.slip_ai_status,o.slip_ai_confidence,o.slip_ai_summary,o.slip_ai_json):''}<div class="evidence-status-grid"><div class="evidence-status ${o.packing_video_url?'done':''}"><strong>Seller Packing</strong><span>${o.packing_video_url?'✓ Video uploaded':'Video required'}</span>${aiEvidenceBadge(o.packing_ai_status,o.packing_ai_confidence,o.packing_ai_summary,o.packing_ai_json)}</div><div class="evidence-status ${o.unboxing_video_url?'done':''}"><strong>Buyer Unboxing</strong><span>${o.unboxing_video_url?'✓ Video uploaded':'Video required'}</span>${aiEvidenceBadge(o.unboxing_ai_status,o.unboxing_ai_confidence,o.unboxing_ai_summary,o.unboxing_ai_json)}</div></div>${o.evidence_match_status?`<div class="notice ${o.evidence_match_status==='Verified'?'good':o.evidence_match_status==='Mismatch'?'bad':'warn'}"><strong>Packing ↔ Unboxing cross-check: ${esc(o.evidence_match_status)}</strong></div>`:''}<div class="toolbar"><label class="btn btn-outline">Upload Slip<input hidden type="file" accept="image/*" capture="environment" onchange="uploadOrderFile(${o.id},'slip',this.files[0])"></label><button class="btn btn-primary" onclick="openEvidenceRecorder(${o.id},'unboxing','orders')">Record Unboxing Video</button></div><div class="sub" style="margin-top:6px">Payment slip: upload a photo or screenshot. Unboxing video: must be recorded live in the app.</div>${o.tracking_number?`<div>Tracking: <strong>${esc(o.tracking_number)}</strong></div>`:''}</section>`).join('')||'<div class="empty">No orders yet.</div>'}`)}
async function uploadOrderFile(order_id,kind,file){if(!file)return;const fd=new FormData();fd.append('order_id',order_id);fd.append('device_id',state.device);fd.append('slip',file);const r=await api('/api/payment-slip',{method:'POST',body:fd});toast(r.ai?.status?`Payment slip uploaded — AI: ${r.ai.status}`:'Payment slip uploaded');orders()}
function sellerOrdersPage(){const back=state.sellerToken?'seller-dashboard':'sell';return shell(`<button class="ghost" onclick="setPage('${back}')">← Back</button><div class="section-head"><div><h1 class="screen-title">${t('seller_orders_title')}</h1><p>Record the required packing video for orders that include your store's items.</p></div></div>${demoBanner()}<section class="panel"><div class="field"><label>Store token</label><input id="sellerTokenInput" value="${esc(state.sellerToken)}" placeholder="Token from Collectra admin"><button class="btn btn-blue" style="margin-top:10px" onclick="sellerOrders()">Load Orders</button></div></section><div id="sellerOrdersList"></div>`)}
async function sellerOrders(){const tokenInput=$('#sellerTokenInput');const token=(tokenInput?tokenInput.value:state.sellerToken).trim();if(!token)return toast('Enter your store token');state.sellerToken=token;localStorage.setItem('collectra_seller_token',token);if(state.page!=='seller-orders'){state.page='seller-orders';render()}try{const r=await api('/api/seller-orders?store_token='+encodeURIComponent(token));state._sellerStoreName=r.store_name;state._sellerOrders=r.orders;renderSellerOrdersList()}catch(e){toast(e.message);const el=$('#sellerOrdersList');if(el)el.innerHTML=''}}
function renderSellerOrdersList(){const el=$('#sellerOrdersList');if(!el)return;const orders=state._sellerOrders||[];el.innerHTML=`<div class="section-head"><div><h2>${esc(state._sellerStoreName||'')}</h2><p>${orders.length} order(s) containing your items</p></div></div>${orders.map(o=>`<section class="panel" style="margin-bottom:14px"><div class="store-title"><div><h2>Order #${o.id}</h2><div class="sub">${new Date(o.created_at).toLocaleString()}</div></div><span class="badge">${esc(o.status)}</span></div>${o.items.map(i=>`<div class="order-row"><div class="grow">${esc(i.title)}</div><strong>${i.qty} × ${money(i.unit_price)}</strong></div>`).join('')}<div class="evidence-status-grid"><div class="evidence-status ${o.packing_video_url?'done':''}"><strong>Your Packing Video</strong><span>${o.packing_video_url?'✓ Video uploaded':'Video required'}</span>${aiEvidenceBadge(o.packing_ai_status,o.packing_ai_confidence,o.packing_ai_summary,o.packing_ai_json)}</div><div class="evidence-status ${o.unboxing_video_url?'done':''}"><strong>Buyer Unboxing</strong><span>${o.unboxing_video_url?'✓ Video uploaded':'Not yet received'}</span>${aiEvidenceBadge(o.unboxing_ai_status,o.unboxing_ai_confidence,o.unboxing_ai_summary,o.unboxing_ai_json)}</div></div>${o.evidence_match_status?`<div class="notice ${o.evidence_match_status==='Verified'?'good':o.evidence_match_status==='Mismatch'?'bad':'warn'}"><strong>Packing ↔ Unboxing cross-check: ${esc(o.evidence_match_status)}</strong></div>`:''}<div class="toolbar">${!o.packing_video_url?`<button class="btn btn-blue" onclick="openEvidenceRecorder(${o.id},'packing','seller-orders')">Record Packing Video</button>`:'<span class="sub">Packing video already submitted for this order.</span>'}</div></section>`).join('')||'<div class="empty">No orders yet for this store.</div>'}`}

const PACKING_STEPS=[
  'Show the full FRONT of the exact card clearly.',
  'Flip the SAME card and show the full BACK clearly.',
  'Show all EDGES, CORNERS and important surface details.',
  'Keep the card continuously in frame while sleeving, top-loading and placing it into the package. No cuts or switching.',
  'Show the SEALED package and shipping label/order number before ending the video.'
];
const UNBOXING_STEPS=[
  'Show the UNOPENED parcel and shipping label/order number.',
  'Keep the parcel continuously in frame while opening it. No cuts or pauses.',
  'Show the card immediately as it is removed from the package.',
  'Show the full FRONT of the received card clearly.',
  'Show the full BACK, then the EDGES/CORNERS and surface details before ending the video.'
];
function evidenceSteps(){return state.evidenceContext?.kind==='packing'?PACKING_STEPS:UNBOXING_STEPS}
function openEvidenceRecorder(orderId,kind,returnPage){stopEvidenceStream();state.evidenceContext={orderId,kind,returnPage:returnPage||'orders'};state.evidenceStep=0;state.evidenceBlob=null;if(state.evidenceReviewUrl){URL.revokeObjectURL(state.evidenceReviewUrl);state.evidenceReviewUrl=''}state.page='evidence-recorder';render()}
function evidenceRecorderPage(){const c=state.evidenceContext;if(!c)return ordersReady();const steps=evidenceSteps();const title=c.kind==='packing'?'Seller Packing Video':'Buyer Unboxing Video';const backPage=c.returnPage||'orders';const backLabel=backPage==='seller-orders'?'← Seller Orders':'← Orders';return shell(`<button class="ghost" onclick="stopEvidenceStream();setPage('${backPage}')">${backLabel}</button><div class="section-head"><div><h1 class="screen-title">${title}</h1><p>One continuous video. Follow every step so the card cannot be switched off-camera.</p></div></div><div class="grid-2 evidence-layout"><section class="panel blue"><div class="evidence-rule">● KEEP RECORDING · NO CUTS · KEEP CARD/PARCEL IN FRAME</div><div class="video-stage">${state.evidenceReviewUrl?`<video class="evidence-video" src="${state.evidenceReviewUrl}" controls playsinline></video>`:`<video id="evidencePreview" class="evidence-video" autoplay muted playsinline></video><div id="cameraPlaceholder" class="camera-placeholder">Camera preview appears here</div>`}</div><div id="evidencePrompt" class="next-prompt"><small>STEP ${state.evidenceStep+1} OF ${steps.length}</small><strong>${esc(steps[state.evidenceStep])}</strong><div class="next-hint">${state.evidenceStep<steps.length-1?'Next: '+esc(steps[state.evidenceStep+1]):'Final step — keep recording until this is clearly shown.'}</div><div id="stepCheckBar" class="step-check-bar"></div></div><div class="toolbar evidence-controls">${!state.evidenceReviewUrl?`<button id="startEvidenceBtn" class="btn btn-primary" onclick="startGuidedRecording()">Start Guided Recording</button><button id="nextEvidenceBtn" class="btn btn-white" onclick="nextEvidenceStep()" disabled>Next Step</button><button id="stopEvidenceBtn" class="btn btn-outline" onclick="stopGuidedRecording()" disabled>Stop & Review</button>`:`<button class="btn btn-outline" onclick="redoEvidence()">Record Again</button><button class="btn btn-primary" onclick="uploadGuidedEvidence()">Upload Required Video</button>`}</div></section><section class="panel yellow"><h2>${c.kind==='packing'?'Packing guide':'Unboxing guide'}</h2><div class="evidence-steps">${steps.map((step,i)=>`<div class="evidence-step ${i<state.evidenceStep?'done':i===state.evidenceStep?'active':''}"><span>${i+1}</span><div>${esc(step)}</div></div>`).join('')}</div><div class="notice warn"><strong>Why this matters:</strong> front, back and the full packing/unboxing sequence remain linked in one continuous video, reducing the chance of swapping a genuine and counterfeit card.</div><div class="notice"><strong>Recording must be done here in the app.</strong> Uploading a video file from your gallery is not accepted, so the recording can't be pre-edited or swapped before it reaches Collectra. If the camera won't open, make sure you allowed camera/microphone permission and are using HTTPS or localhost.</div></section></div>`)}
async function startGuidedRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('In-app recording needs camera permission and HTTPS (or localhost). Please enable camera access and try again.');return}try{state.evidenceStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:true});const video=$('#evidencePreview');video.srcObject=state.evidenceStream;$('#cameraPlaceholder')?.remove();const supported=['video/mp4','video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));const opts={videoBitsPerSecond:1800000};if(supported)opts.mimeType=supported;state.evidenceChunks=[];state.evidenceRecorder=new MediaRecorder(state.evidenceStream,opts);state.evidenceRecorder.ondataavailable=e=>{if(e.data?.size)state.evidenceChunks.push(e.data)};state.evidenceRecorder.onstop=()=>{const type=state.evidenceRecorder?.mimeType||'video/webm';state.evidenceBlob=new Blob(state.evidenceChunks,{type});state.evidenceReviewUrl=URL.createObjectURL(state.evidenceBlob);stopEvidenceStream();render()};state.evidenceRecorder.start(800);state.evidenceStartedAt=Date.now();state.evidenceStep=0;$('#startEvidenceBtn').disabled=true;$('#startEvidenceBtn').textContent='Recording…';$('#nextEvidenceBtn').disabled=false;$('#stopEvidenceBtn').disabled=true;updateEvidenceUI()}catch(e){console.error(e);toast('Camera could not start. Check camera/microphone permission and try again.') }}
function captureEvidenceFrame(){const video=$('#evidencePreview');if(!video||!video.videoWidth)return null;const canvas=document.createElement('canvas');const scale=Math.min(1,480/video.videoWidth);canvas.width=video.videoWidth*scale;canvas.height=video.videoHeight*scale;canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);return new Promise(res=>canvas.toBlob(b=>res(b),'image/jpeg',0.6))}
async function checkEvidenceStepFrame(stepText){try{const blob=await captureEvidenceFrame();if(!blob)return;const fd=new FormData();fd.append('frame',blob,'frame.jpg');fd.append('step_text',stepText);fd.append('kind',state.evidenceContext?.kind||'packing');const r=await api('/api/evidence-step-check',{method:'POST',body:fd});const bar=$('#stepCheckBar');if(!bar)return;if(r.ok){bar.className='step-check-bar ok';bar.textContent='✓ Looks good';setTimeout(()=>{if(bar)bar.textContent=''},2000)}else{bar.className='step-check-bar warn';bar.textContent='⚠ '+(r.message||'Check the framing for this step')}}catch(e){}}
function nextEvidenceStep(){const steps=evidenceSteps();if(!state.evidenceRecorder||state.evidenceRecorder.state!=='recording')return toast('Start recording first');const leavingStep=steps[state.evidenceStep];checkEvidenceStepFrame(leavingStep);if(state.evidenceStep<steps.length-1)state.evidenceStep++;updateEvidenceUI();if(state.evidenceStep===steps.length-1)$('#stopEvidenceBtn').disabled=false}
function updateEvidenceUI(){const steps=evidenceSteps(),p=$('#evidencePrompt');if(p)p.innerHTML=`<small>STEP ${state.evidenceStep+1} OF ${steps.length}</small><strong>${esc(steps[state.evidenceStep])}</strong><div class="next-hint">${state.evidenceStep<steps.length-1?'Next: '+esc(steps[state.evidenceStep+1]):'Final step — keep recording until this is clearly shown.'}</div><div id="stepCheckBar" class="step-check-bar"></div>`;$$('.evidence-step').forEach((el,i)=>{el.classList.toggle('done',i<state.evidenceStep);el.classList.toggle('active',i===state.evidenceStep)})}
function stopGuidedRecording(){if(!state.evidenceRecorder||state.evidenceRecorder.state!=='recording')return;if(state.evidenceStep<evidenceSteps().length-1)return toast('Follow every guide step before stopping');if(Date.now()-state.evidenceStartedAt<10000)return toast('Keep recording long enough to clearly show every step');checkEvidenceStepFrame(evidenceSteps()[state.evidenceStep]);state.evidenceRecorder.stop()}
function stopEvidenceStream(){if(state.evidenceStream){state.evidenceStream.getTracks().forEach(t=>t.stop());state.evidenceStream=null}}
function redoEvidence(){stopEvidenceStream();if(state.evidenceReviewUrl)URL.revokeObjectURL(state.evidenceReviewUrl);state.evidenceReviewUrl='';state.evidenceBlob=null;state.evidenceStep=0;render()}
async function uploadGuidedEvidence(){const c=state.evidenceContext;if(!c||!state.evidenceBlob)return toast('Record or choose the required video first');if(c.kind==='packing'&&!state.sellerToken){const t=prompt('Enter your store token to upload the packing video:');if(!t)return toast('Store token required');state.sellerToken=t;localStorage.setItem('collectra_seller_token',t)}const steps=evidenceSteps();const ext=state.evidenceBlob.type.includes('mp4')?'mp4':'webm';const file=state.evidenceBlob instanceof File?state.evidenceBlob:new File([state.evidenceBlob],`${c.kind}-order-${c.orderId}.${ext}`,{type:state.evidenceBlob.type||'video/webm'});const fd=new FormData();fd.append('order_id',c.orderId);fd.append('device_id',state.device);fd.append('kind',c.kind);fd.append('guide_steps',JSON.stringify(steps));fd.append('evidence',file);if(c.kind==='packing')fd.append('store_token',state.sellerToken);try{const r=await api('/api/order-evidence',{method:'POST',body:fd});const label=c.kind==='packing'?'Packing':'Unboxing';toast(r.ai?.status?`${label} video uploaded — AI: ${r.ai.status}`:`${label} video uploaded`);state.evidenceBlob=null;if(state.evidenceReviewUrl)URL.revokeObjectURL(state.evidenceReviewUrl);state.evidenceReviewUrl='';state.evidenceContext=null;if(c.returnPage==='seller-orders')sellerOrders();else orders()}catch(e){if(c.kind==='packing'&&/token/i.test(e.message)){state.sellerToken='';localStorage.removeItem('collectra_seller_token')}toast(e.message)}}

function admin(){return shell(`<div class="section-head"><div><h1 class="screen-title">Collectra Admin</h1><p>Hidden prototype area for seller approvals, human tickets and reference cards.</p></div></div><section class="panel"><div class="field"><label>Admin key</label><input id="adminKey" type="password" value="${esc(state.adminKey)}"><button class="btn btn-blue" style="margin-top:10px" onclick="loadAdmin()">Open Dashboard</button></div><div id="adminBody"></div></section>`)}
async function loadAdmin(){state.adminKey=$('#adminKey').value;localStorage.setItem('collectra_admin_key',state.adminKey);try{state._admin=await api('/api/admin/dashboard',{headers:{'X-Admin-Key':state.adminKey}});renderAdminBody()}catch(e){toast(e.message)}}
function copyToken(t){navigator.clipboard&&navigator.clipboard.writeText(t).then(()=>toast('Token copied')).catch(()=>toast(t))}
function renderAdminBody(){const d=state._admin, el=$('#adminBody');if(!d||!el)return;el.innerHTML=`<div class="admin-grid" style="margin-top:20px"><section><h2>Stores &amp; Seller Tokens</h2><p class="sub">Give the seller their token so they can log in on the Sell page.</p>${(d.stores||[]).map(s=>`<div class="admin-row"><div class="grow"><strong>${esc(s.name)}</strong>${s.verified?' <span class="badge">Verified</span>':''}<div class="sub" style="font-family:monospace;word-break:break-all">${esc(s.token)}</div></div><button class="btn btn-outline" onclick="copyToken('${esc(s.token)}')">Copy</button></div>`).join('')||'No stores yet.'}</section><section><h2>Seller Applications</h2>${d.applications.map(a=>`<div class="admin-row"><div class="grow"><strong>${esc(a.shop_name||a.email)}</strong><div class="sub">${esc(a.email)} · ${esc(a.status)}</div></div>${a.status==='pending'?`<button class="btn btn-primary" onclick="approveSeller(${a.id},'${esc(a.shop_name)}')">Approve</button>`:''}</div>`).join('')||'None'}</section><section><h2>Human Support</h2>${d.tickets.map(t=>`<div class="admin-row"><div><strong>${esc(t.email||'No email')}</strong><div>${esc(t.message)}</div></div></div>`).join('')||'None'}</section><section><h2>AI Review Queue</h2>${d.verifications.map(v=>`<div class="admin-row"><div class="grow"><strong>${esc(v.verdict)} · ${v.confidence}/100</strong><div class="sub">${esc(v.category)} ${esc(v.card_name)}</div></div></div>`).join('')||'None'}</section><section><h2>Seller Demo Feedback</h2><p class="sub">Public link to send testers: <code>${location.origin}/#seller-demo</code></p>${(d.demo_feedback||[]).map(f=>`<div class="admin-row" style="display:block"><div style="display:flex;justify-content:space-between;align-items:center"><strong>${'★'.repeat(f.rating)}${'☆'.repeat(5-f.rating)}</strong><span class="sub">${new Date(f.created_at).toLocaleString()}</span></div>${f.liked?`<div class="sub" style="margin-top:6px"><strong>Liked:</strong> ${esc(f.liked)}</div>`:''}${f.improve?`<div class="sub" style="margin-top:4px"><strong>Improve:</strong> ${esc(f.improve)}</div>`:''}</div>`).join('')||'No feedback submitted yet.'}</section><section><h2>Add Verified Reference</h2><form id="refForm" class="form-grid" onsubmit="uploadReference(event)"><div class="field"><label>Category</label><select name="category"><option>K-pop</option><option>T-pop</option><option>Other</option></select></div><div class="field"><label>Card name</label><input name="card_name"></div><div class="field"><label>Set / release</label><input name="set_name"></div><div class="field"><label>Verified reference image</label><input name="image" type="file" accept="image/*" required></div><button class="btn btn-blue">Upload Reference</button></form></section></div>`}
async function approveSeller(id,name){const store_name=prompt('Store name',name||'')||name;const r=await api('/api/admin/approve-seller',{method:'POST',headers:{'Content-Type':'application/json','X-Admin-Key':state.adminKey},body:JSON.stringify({application_id:id,store_name})});alert('Approved. Give this store token to the seller:\n\n'+r.store_token);loadAdmin()}
async function uploadReference(e){e.preventDefault();const fd=new FormData(e.target);const r=await api('/api/admin/reference',{method:'POST',headers:{'X-Admin-Key':state.adminKey},body:fd});toast('Reference uploaded');e.target.reset();loadAdmin()}

function render(){let html='';switch(state.page){case'home':html=home();break;case'shops':html=shops();break;case'store':html=storePage();break;case'verify':html=verify();break;case'saved':html=saved();break;case'sell':html=sell();break;case'seller-login':html=sellerLoginPage();break;case'seller-dashboard':html=sellerDashboardPage();break;case'seller-demo':html=sellerDemoPage();break;case'seller-demo-feedback':html=sellerDemoFeedbackPage();break;case'seller-tools':html=sellerTools();break;case'support':html=support();break;case'cart':html=cart();break;case'checkout':checkout();return;case'checkout-ready':html=checkoutReady();break;case'profile':html=profile();break;case'addresses':addresses();return;case'addresses-ready':html=addressesReady();break;case'orders':orders();return;case'orders-ready':html=ordersReady();break;case'seller-orders':html=sellerOrdersPage();if(state.sellerToken)sellerOrders();break;case'evidence-recorder':html=evidenceRecorderPage();break;case'admin':html=admin();break;default:state.page=DEMO_ONLY?'seller-demo':'home';html=DEMO_ONLY?sellerDemoPage():home()}$('#app').innerHTML=html;if(state.page==='admin'&&state._admin)renderAdminBody()}
bootstrap();
